// Entrada: mail de Outlook (subject + body). Salida: tipo, nombre, apellido, email,
// telefono, dni, nroPedido y comentario. Los campos se leen de líneas "Etiqueta: valor".
const results = [];

const FOOTER = /Este mensaje fue enviado desde el formulario de contacto de su sitio web\.?/gi;

// Entidades HTML nombradas habituales en español (las numéricas se decodifican aparte)
const ENTIDADES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
  aacute: 'á', eacute: 'é', iacute: 'í', oacute: 'ó', uacute: 'ú', uuml: 'ü', ntilde: 'ñ',
  Aacute: 'Á', Eacute: 'É', Iacute: 'Í', Oacute: 'Ó', Uacute: 'Ú', Uuml: 'Ü', Ntilde: 'Ñ',
  iexcl: '¡', iquest: '¿', ordm: 'º', ordf: 'ª', deg: '°'
};

const decodificar = (s) => s.replace(/&(#x[0-9a-f]+|#\d+|[a-z][a-z0-9]*);/gi, (m, e) => {
  if (e[0] === '#') {
    const cp = e[1].toLowerCase() === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
    return cp > 0 && cp <= 0x10ffff ? String.fromCodePoint(cp) : m;
  }
  return Object.prototype.hasOwnProperty.call(ENTIDADES, e) ? ENTIDADES[e] : m;
});

// HTML -> texto, un campo por línea (las celdas de una misma fila quedan en la misma línea)
const htmlATexto = (html) => decodificar(
  String(html)
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/<(head|style|script|title)\b[\s\S]*?<\/\1>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|dt|dd|h[1-6]|table|ul|ol)>/gi, '\n')
    .replace(/<\/t[dh]>/gi, ' ')
    .replace(/<[^>]+>/g, '')
).replace(/ /g, ' ');

// Cuerpo del mail. Outlook devuelve body = { contentType, content } (con salida "raw" del trigger);
// si se usa salida "simple" solo llega bodyPreview (texto truncado a ~255 caracteres).
const obtenerTexto = (j) => {
  const b = j.body;
  if (b && typeof b === 'object' && b.content) {
    return String(b.contentType).toLowerCase() === 'text' ? String(b.content) : htmlATexto(b.content);
  }
  if (typeof b === 'string' && b) return /<[a-z!\/][^>]*>/i.test(b) ? htmlATexto(b) : b;
  if (j.text) return String(j.text);
  if (j.html) return htmlATexto(j.html);
  return String(j.bodyPreview || '');
};

const labels = ['Nombre', 'Apellido', 'Email', 'Teléfono', 'Telefono', 'DNI', 'Nro de pedido', 'Mensaje', 'Comentarios'];
const multiline = ['mensaje', 'comentarios'];
const reEtiqueta = new RegExp('^(' + labels.join('|') + ')\\s*:\\s*(.*)$', 'i');

for (const item of $input.all()) {
  const j = item.json;

  const text = obtenerTexto(j).split('\r').join('');

  // Tipo de solicitud: solo asunto + título del formulario (primera línea del cuerpo).
  // No se mira lo que escribe el cliente: una palabra suelta no debe cambiar el flujo.
  const titulo = text.split('\n').map((l) => l.trim()).find((l) => l) || '';
  const hay = ((j.subject || '') + '\n' + titulo).toLowerCase();
  let tipo = 'Desconocido';
  if (hay.includes('arrepentimiento')) tipo = 'Arrepentimiento de compra';
  else if (hay.includes('contacto') || text.toLowerCase().includes('formulario de contacto de su sitio web')) tipo = 'Solicitud de Contacto';

  // Parseo de campos "Etiqueta: valor" (Mensaje/Comentarios pueden ocupar varias lineas)
  const fields = {};
  let current = null;

  for (const raw of text.split('\n')) {
    const line = raw.trim();
    const m = line.match(reEtiqueta);
    if (m) {
      current = m[1].toLowerCase();
      fields[current] = m[2].trim();
    } else if (current && multiline.includes(current) && line) {
      fields[current] += (fields[current] ? ' ' : '') + line;
    }
  }

  const esContacto = tipo === 'Solicitud de Contacto';
  const esArrep = tipo === 'Arrepentimiento de compra';

  // Comentario sin la frase fija del formulario
  // Si el mail no tiene el formato del formulario (ninguna etiqueta), todo el texto pasa a ser el comentario
  const sinFormato = Object.keys(fields).length === 0;
  const textoLibre = text.split('\n').map((l) => l.trim()).filter(Boolean).join(' ').slice(0, 2000);
  const comentario = (fields['mensaje'] || fields['comentarios'] || (sinFormato ? textoLibre : '')).replace(FOOTER, '').trim();

  results.push({
    json: {
      tipo: tipo,
      nombre: fields['nombre'] || '',
      apellido: fields['apellido'] || '',
      email: fields['email'] || '',
      telefono: esContacto ? (fields['teléfono'] || fields['telefono'] || '') : '',
      dni: esArrep ? (fields['dni'] || '') : '',
      nroPedido: esArrep ? (fields['nro de pedido'] || '') : '',
      comentario: comentario
    }
  });
}

return results;
